-- ============================================
-- 084_sms_per_sheet_kind.sql
--
-- 출고안내문자를 시트 종류(커스텀 상품 주문시트 / 월별 답례품 시트)별로 나눈다 (운영 결정 2026-09-15).
--   · 본문을 시트 종류별로 따로 설정 — 커스텀 본문 컬럼 추가 (비우면 답례품 본문을 그대로 쓴다).
--   · 1회 발송 규칙을 "주문 × 시트 종류" 단위로 — 커스텀과 답례품을 함께 산 고객은 각각 1통씩 받는다.
--     발송 이력은 template_code 로 구분한다: 답례품 = SMS_출고완료안내, 커스텀 = SMS_출고완료안내_커스텀.
--
-- 기존 이력 재분류: 지금까지는 두 시트 모두 SMS_출고완료안내 로 기록됐다. 2026-09-15 시트 대조 결과
--   (기록된 송장번호가 어느 시트의 행인지, 송장 없는 레거시 키는 그 주문이 한쪽 시트에만 있는지)로
--   커스텀 시트 발송 64건만 커스텀 코드로 옮긴다. 판별 불가 1건(테스트 주문 123456)과 월별 160건은 그대로.
--   2026-09-14T09:54:08.322+00:00 이후 기록은 대상이 아니다 — 같은 출고(주문#송장)는 코드와 무관하게 서버가 막는다.
--
-- 멱등: 이미 옮긴 행은 template_code 조건에 걸리지 않는다.
-- ============================================

ALTER TABLE bg_site_settings
  ADD COLUMN IF NOT EXISTS sms_ship_template_custom TEXT;

COMMENT ON COLUMN bg_site_settings.sms_ship_template_custom IS
  '커스텀 상품 주문시트 출고안내 문자 본문 (084). NULL = 답례품 본문(sms_ship_template) 사용';

